import{_ as e,o as a,c as r,am as i}from"./chunks/framework.BCmjHDVz.js";const g=JSON.parse('{"title":"Performance benchmarks","description":"","frontmatter":{},"headers":[],"relativePath":"manual/benchmarks.md","filePath":"manual/benchmarks.md","lastUpdated":null}'),n={name:"manual/benchmarks.md"};function s(l,t,d,o,c,h){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="Performance-benchmarks" tabindex="-1">Performance benchmarks <a class="header-anchor" href="#Performance-benchmarks" aria-label="Permalink to &quot;Performance benchmarks {#Performance-benchmarks}&quot;">​</a></h1><p>Copulas.jl uses two complementary benchmark systems.</p><h2 id="Performance-over-time" tabindex="-1">Performance over time <a class="header-anchor" href="#Performance-over-time" aria-label="Permalink to &quot;Performance over time {#Performance-over-time}&quot;">​</a></h2><p><a href="https://github.com/KristofferC/Tachometer.jl" target="_blank" rel="noreferrer">Tachometer</a> runs the native Julia suite on pull requests, compares changes with their merge base, and records default-branch results. Its dashboard is published alongside this documentation at <a href="https://lrnv.github.io/Copulas.jl/benchmarks/" target="_blank" rel="noreferrer">the Copulas.jl benchmark dashboard</a>.</p><h2 id="Comparison-with-R" tabindex="-1">Comparison with R <a class="header-anchor" href="#Comparison-with-R" aria-label="Permalink to &quot;Comparison with R {#Comparison-with-R}&quot;">​</a></h2><p>The cross-language suite compares Copulas.jl with R&#39;s <a href="https://cran.r-project.org/package=copula" target="_blank" rel="noreferrer"><code>copula</code></a> package. The initial set covers representative common operations rather than every family and dimension:</p><ul><li><p>Clayton, Gumbel, and Gaussian sampling;</p></li><li><p>Gumbel and Gaussian log-density evaluation;</p></li><li><p>pseudo-observations;</p></li><li><p>Gumbel inverse-Kendall fitting;</p></li><li><p>Gaussian maximum-likelihood fitting.</p></li></ul><p>Julia and R run as independent native processes on the same machine. The suite excludes process startup, package loading, fixture parsing, model construction, and Julia compilation. Full runs alternate three Julia and R process rounds and report the median steady-state time for each language.</p><p>Before reporting timings, deterministic outputs are compared numerically on shared committed fixtures. Sampling uses independent seeded streams and receives local range and finiteness checks. A failed correctness check invalidates the entire timing report.</p><p>The complete specification, locked environments, raw-result schema, and local reproduction instructions live in <a href="https://github.com/lrnv/Copulas.jl/tree/main/benchmark/cross_language" target="_blank" rel="noreferrer"><code>benchmark/cross_language</code></a>. Every documentation build runs the comparison first and embeds that run&#39;s table below. Pull-request previews use the reduced smoke workload; default-branch and release-tag documentation use the full workload with three alternating process rounds. The raw JSON and rendered table are retained as artifacts of the same workflow. The manually dispatched <strong>Julia vs R benchmarks</strong> workflow remains available for diagnostic runs that do not publish documentation.</p><p>&lt;!– BEGIN JULIA_VS_R_RESULTS –&gt;</p><h3 id="Results-from-this-documentation-build" tabindex="-1">Results from this documentation build <a class="header-anchor" href="#Results-from-this-documentation-build" aria-label="Permalink to &quot;Results from this documentation build {#Results-from-this-documentation-build}&quot;">​</a></h3><p>Mode: <code>smoke</code>; rounds: Julia 1, R 1; correctness: <strong>passed</strong>.</p><p>Generated at <code>2026-08-11T12:44:41.053</code> from <a href="https://github.com/lrnv/Copulas.jl/commit/541dffaa4e992090ac0b4cdcf92081f336c5b011" target="_blank" rel="noreferrer"><code>541dffaa</code></a>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Target</th><th style="text-align:right;">Julia median</th><th style="text-align:right;">R median</th><th style="text-align:right;">R / Julia</th><th style="text-align:center;">Validation</th></tr></thead><tbody><tr><td style="text-align:right;"><code>data/pseudos_5x10000</code></td><td style="text-align:right;">50.84 μs</td><td style="text-align:right;">232.86 μs</td><td style="text-align:right;">4.58×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>density/gaussian_d10</code></td><td style="text-align:right;">222.32 μs</td><td style="text-align:right;">1.31 ms</td><td style="text-align:right;">5.89×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>density/gumbel_d5</code></td><td style="text-align:right;">303.62 μs</td><td style="text-align:right;">2.80 ms</td><td style="text-align:right;">9.23×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>fitting/gaussian_mle</code></td><td style="text-align:right;">27.69 μs</td><td style="text-align:right;">141.68 ms</td><td style="text-align:right;">5116.22×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>fitting/gumbel_itau</code></td><td style="text-align:right;">28.39 μs</td><td style="text-align:right;">946.95 μs</td><td style="text-align:right;">33.35×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>sampling/clayton_d5</code></td><td style="text-align:right;">383.21 μs</td><td style="text-align:right;">193.68 μs</td><td style="text-align:right;">0.51×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>sampling/gaussian_d10</code></td><td style="text-align:right;">98.41 μs</td><td style="text-align:right;">748.26 μs</td><td style="text-align:right;">7.60×</td><td style="text-align:center;">✓</td></tr><tr><td style="text-align:right;"><code>sampling/gumbel_d5</code></td><td style="text-align:right;">130.29 μs</td><td style="text-align:right;">277.36 μs</td><td style="text-align:right;">2.13×</td><td style="text-align:center;">✓</td></tr></tbody></table><p>Steady-state execution only: startup, package loading, fixture parsing, model construction, and Julia compilation are excluded. Sampling rows receive local validity checks; deterministic density, rank, and fitting rows are checked numerically across languages.</p><p>Runner: <code>Linux</code> / <code>x86_64</code>. Julia 1.12.1 with Copulas.jl 0.1.39; R version 4.6.1 (2026-06-24) with copula 1.1.7.</p><p>&lt;!– END JULIA_VS_R_RESULTS –&gt;</p><div class="tip custom-block"><div class="custom-block-title">Tip: Interpreting results</div><div class="custom-block-content"><p>GitHub-hosted runners are useful for reproducibility but are shared infrastructure. Their ratios are indicative, not universal claims about all hardware. Allocation figures are retained separately but are not compared because Julia and R memory instrumentation measures different things.</p></div></div>',19)])])}const m=e(n,[["render",s]]);export{g as __pageData,m as default};
